export function resolveBrandIconKey(providerIdOrName?: string): string | null {
  const s = (providerIdOrName || "").toLowerCase().trim();
  if (!s) return null;
  if (s === "const" || s.includes("const-router") || s.includes("const router")) return "const";
  if (s.includes("openai") || s.includes("chatgpt") || s.includes("codex")) return "openai";
  if (s.includes("claude")) return "claude";
  if (s.includes("anthropic")) return "anthropic";
  if (s.includes("gemini")) return "gemini";
  if (s.includes("google")) return "google";
  if (s.includes("copilot") || s.includes("github")) return "github-copilot";
  if (s.includes("openrouter")) return "openrouter";
  if (s.includes("xai") || s.includes("grok")) return "xai";
  if (s.includes("kimi") || s.includes("moonshot")) return "kimi";
  if (s.includes("gitlab")) return "gitlab";
  if (s.includes("deepseek")) return "deepseek";
  if (s.includes("mistral")) return "mistral";
  if (s.includes("groq")) return "groq";
  if (s.includes("ollama")) return "ollama";
  return null;
}

export function BrandLogo({
  provider,
  className,
}: {
  provider: string;
  className?: string;
}) {
  const key = resolveBrandIconKey(provider);
  if (!key) return null;
  if (key === "const") {
    const base = typeof window !== "undefined" && window.location.protocol === "file:" ? "./" : "/";
    return (
      <>
        <img
          src={`${base}router-logo-light-transparent.svg`}
          alt=""
          className={cn("inline-block dark:hidden object-contain shrink-0", className)}
        />
        <img
          src={`${base}router-logo-dark-transparent.svg`}
          alt=""
          className={cn("hidden dark:inline-block object-contain shrink-0", className)}
        />
      </>
    );
  }
  if (!THESVG_BRAND_ICONS[key]) return null;
  const { light, dark } = THESVG_BRAND_ICONS[key];
  if (light === dark) {
    return (
      <span
        aria-hidden="true"
        className={cn("inline-flex items-center justify-center shrink-0 [&>svg]:w-full [&>svg]:h-full", className)}
        dangerouslySetInnerHTML={{ __html: light }}
      />
    );
  }
  return (
    <>
      <span
        aria-hidden="true"
        className={cn("inline-flex dark:hidden items-center justify-center shrink-0 [&>svg]:w-full [&>svg]:h-full", className)}
        dangerouslySetInnerHTML={{ __html: light }}
      />
      <span
        aria-hidden="true"
        className={cn("hidden dark:inline-flex items-center justify-center shrink-0 [&>svg]:w-full [&>svg]:h-full", className)}
        dangerouslySetInnerHTML={{ __html: dark }}
      />
    </>
  );
}
